function parseData(str){
  const m = (str||'').match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  return m ? (m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0')) : null;
}
function modalidade(r){
  const txt = ((r.json.title||'')+' '+(r.json.job_type||'')+' '+(r.json.description||'')).toLowerCase();
  if (/remoto|remote|100% remote|trabalho a dist/.test(txt)) return 'Remoto';
  if (/híbrido|hibrido|hybrid|hybrid/.test(txt)) return 'Híbrido';
  if (/presencial|onsite|on-site|on site/.test(txt)) return 'Local';
  if (r.json.is_remote === true) return 'Remoto';
  if (r.json.is_remote === false) return 'Local';
  return 'Indefinido';
}
const hoje = $now.toFormat('yyyy-MM-dd');
const limiar = 65;
const linhas = $input.all();
const validas = linhas.filter(r => {
  const s = parseFloat(r.json.Score);
  const dt = parseData(r.json.Date || r.json.date || '');
  return !isNaN(s) && s >= limiar && dt === hoje;
});
const isBR = r => /brasil|brazil/i.test(r.json.location || '');
const br = validas.filter(isBR).sort((a,b)=>parseFloat(b.json.Score)-parseFloat(a.json.Score)).slice(0,15);
const ext = validas.filter(r=>!isBR(r)).sort((a,b)=>parseFloat(b.json.Score)-parseFloat(a.json.Score)).slice(0,15);
function monta(arr, cabecalho){
  let s=''; arr.forEach((r,i)=>{
    const url=r.json.job_url||'';
    const mod = modalidade(r);
    s+=(i+1)+'. ['+mod+'] '+r.json.title+'\n   '+r.json.company+' ('+r.json.location+') — Score '+r.json.Score+'\n   '+url+'\n\n';
  });
  return cabecalho+'\n'+(s||'Sem vagas nesta categoria hoje.');
}
const brText = monta(br, '🇧🇷 BRASIL (Remoto) — Top '+br.length);
const extText = monta(ext, '🌍 EXTERNO (Realocacao) — Top '+ext.length);
if (br.length===0 && ext.length===0){
  return [{ json: { parte:'BR', data:hoje, total:0, resumo:'Sem vagas relevantes (Score>=65) de HOJE.' } }];
}
return [
  { json: { parte:'BR', data:hoje, total:br.length, resumo: brText } },
  { json: { parte:'EXT', data:hoje, total:ext.length, resumo: extText } }
];
